<template>
    <article
      class="settings-section  w-full md:w-9/12 xl:w-10/12 p-12 pr-0 pl-0 rounded-[32px] !bg-white">
    <div class="header-section">
    
      <div class="content-section px-12">
        <h3 class="text-lg font-medium mb-4 bg-[#f5f7fa] px-6 py-4 rounded-2xl">{{ $t('loginShortCode') }}</h3>
     
        <div class="template-header">
      <h2>{{ $t('templates.title') }}</h2>
      <button @click="openAddTemplateModal" class="btn btn-primary">
        {{ $t('templates.add_new') }}
      </button>
    </div>

    <div v-if="loading" class="loading">
      {{ $t('common.loading') }}
    </div>

    <div v-else-if="templates.length === 0" class="no-templates">
      {{ $t('templates.no_templates') }}
    </div>

    <div v-else class="template-list">
      <div v-for="template in templates" :key="template.id" class="template-item">
        <div class="template-info">
          <h3>{{ template.title }}</h3>
          <p>{{ template.templateText }}</p>
          <span class="template-status" :class="getStatusClass(template.status)">
            {{ getStatusText(template.status) }}
          </span>
        </div>
        <div class="template-actions">
          <button @click="editTemplate(template)" class="btn btn-edit">
            {{ $t('common.edit') }}
          </button>
          <button @click="confirmDeleteTemplate(template)" class="btn btn-delete">
            {{ $t('common.delete') }}
          </button>
        </div>
      </div>
    </div>

    <div class="pagination" v-if="totalPages > 1">
      <button 
        @click="loadTemplates(currentPage - 1)" 
        :disabled="currentPage === 1"
      >
        {{ $t('common.previous') }}
      </button>
      <span>{{ currentPage }} / {{ totalPages }}</span>
      <button 
        @click="loadTemplates(currentPage + 1)" 
        :disabled="currentPage === totalPages"
      >
        {{ $t('common.next') }}
      </button>
    </div>

    <!-- Modal for Add/Edit Template -->
    <div v-if="showModal" class="modal">
      <div class="modal-content">
        <h2>{{ isEditing ? $t('templates.edit') : $t('templates.add_new') }}</h2>
        <form @submit.prevent="saveTemplate">
          <div class="form-group">
            <label>{{ $t('templates.title') }}</label>
            <input 
              v-model="currentTemplate.title" 
              type="text" 
              required 
              maxlength="32"
            />
          </div>
          <div class="form-group">
            <label>{{ $t('templates.template_text') }}</label>
            <textarea 
              v-model="currentTemplate.templateText" 
              required
            ></textarea>
            <small>{{ $t('templates.variable_hint') }}</small>
          </div>
          <div class="modal-actions">
            <button type="button" @click="closeModal" class="btn btn-cancel">
              {{ $t('common.cancel') }}
            </button>
            <button type="submit" class="btn btn-primary">
              {{ isEditing ? $t('common.update') : $t('common.save') }}
            </button>
          </div>
        </form>
      </div>
    </div>

    <!-- Confirmation Modal -->
    <div v-if="showConfirmModal" class="modal">
      <div class="modal-content">
        <h2>{{ $t('templates.delete_confirm_title') }}</h2>
        <p>{{ $t('templates.delete_confirm_message') }}</p>
        <div class="modal-actions">
          <button @click="showConfirmModal = false" class="btn btn-cancel">
            {{ $t('common.cancel') }}
          </button>
          <button @click="deleteTemplate" class="btn btn-delete">
            {{ $t('common.delete') }}
          </button>
        </div>
      </div>
    </div>
      </div>
    </div>

  </article>
</template>

<script>
import axios from 'axios'

export default {
  data() {
    return {
      translations: window.sms_ir_login?.translations || {},
      templates: [],
      loading: true,
      currentPage: 1,
      totalPages: 1,
      showModal: false,
      showConfirmModal: false,
      isEditing: false,
      currentTemplate: {
        id: null,
        title: '',
        templateText: ''
      }
    }
  },
  mounted() {
    this.loadTemplates()
  },
  methods: {
    async loadTemplates(page = 1) {
      this.loading = true
      try {
        const response = await axios.post(window.sms_ir_login.ajaxUrl, new URLSearchParams({
          action: 'sms_ir_get_templates',
          page: page,
          size: 10,
          nonce: window.sms_ir_login.nonce
        }), {
          headers: {
            'Content-Type': 'application/x-www-form-urlencoded'
          }
        })
        
        // Safely handle the response
        const data = response.data?.data || {}
        this.templates = data.items || []
        this.currentPage = data.pageNumber || page
        this.totalPages = data.totalPagesCount || 1
      } catch (error) {
        this.$toast.error(this.$t('errors.template_load_failed'))
        // Set default values in case of error
        this.templates = []
        this.currentPage = page
        this.totalPages = 1
      } finally {
        this.loading = false
      }
    },
    openAddTemplateModal() {
      this.currentTemplate = { title: '', templateText: '' }
      this.isEditing = false
      this.showModal = true
    },
    editTemplate(template) {
      this.currentTemplate = { ...template }
      this.isEditing = true
      this.showModal = true
    },
    async saveTemplate() {
      try {
        const method = this.isEditing ? 'update' : 'add'
        const data = new URLSearchParams({
          action: `sms_ir_${method}_template`,
          nonce: window.sms_ir_login.nonce,
          ...this.currentTemplate
        })
        
        const response = await axios.post(window.sms_ir_login.ajaxUrl, data, {
          headers: {
            'Content-Type': 'application/x-www-form-urlencoded'
          }
        })
        
        this.$toast.success(
          this.isEditing 
            ? this.$t('templates.update_success') 
            : this.$t('templates.add_success')
        )
        
        this.closeModal()
        this.loadTemplates(this.currentPage)
      } catch (error) {
        this.$toast.error(this.$t('errors.template_save_failed'))
      }
    },
    async deleteTemplate() {
      try {
        const data = new URLSearchParams({
          action: 'sms_ir_delete_template',
          nonce: window.sms_ir_login.nonce,
          id: this.currentTemplate.id
        })
        
        const response = await axios.post(window.sms_ir_login.ajaxUrl, data, {
          headers: {
            'Content-Type': 'application/x-www-form-urlencoded'
          }
        })
        
        this.$toast.success(this.$t('templates.delete_success'))
        
        this.showConfirmModal = false
        this.loadTemplates(this.currentPage)
      } catch (error) {
        this.$toast.error(this.$t('errors.template_delete_failed'))
      }
    },
    confirmDeleteTemplate(template) {
      this.currentTemplate = template
      this.showConfirmModal = true
    },
    closeModal() {
      this.showModal = false
      this.showConfirmModal = false
    },
    getStatusClass(status) {
      const statusMap = {
        1: 'pending',
        2: 'verified',
        3: 'unverified'
      }
      return statusMap[status] || 'unknown'
    },
    getStatusText(status) {
      const statusMap = {
        1: this.$t('templates.status.pending'),
        2: this.$t('templates.status.verified'),
        3: this.$t('templates.status.unverified')
      }
      return statusMap[status] || this.$t('templates.status.unknown')
    }
  }
}
</script>

