              </label>
              <div class="flex flex-col">
                <div class="text font-extralight">{{ $t('enableRateLimit') }}</div>
                <div class="sub-text text-xs font-extralight text-[#696767]">
                  {{ $t('rateLimitDescription') }}
                </div>
              </div>
            </div>

            <div v-if="settings.settings.rate_limit_active" class="grid grid-cols-2 gap-4">
              <div class="flex flex-col">
                <label class="text-sm mb-1">{{ $t('maxAttempts') }}</label>
                <input
                  v-model="settings.settings.max_attempts"
