              <label class="text-sm mb-1">{{ $t('resendDelay') }} ({{ $t('seconds') }})</label>
              <input
                v-model="settings.settings.resend_delay"
                type="number"
                class="!border !border-[#C2C2C2] !rounded-md !focus:ring-white !focus:ring-0"
