  </article>
</template>

<script>
export default {
  props: {
    settings: {
      type: Object,
      required: true
    }
  },
  created() {
    if (!this.settings.settings) {
      this.settings.settings = {};
    }
    
    const defaults = {
      api_key: '',
      template_id: null,
      rate_limit_active: true,
      max_attempts: 5,
      ban_duration: 600,
      otp_expiry: 60,
      resend_delay: 60,
    };

    for (const [key, value] of Object.entries(defaults)) {
      if (this.settings.settings[key] === undefined) {
        this.settings.settings[key] = value;
      }
    }
  },

};
</script>