<template>
  <div class="space-y-4">
    <h3 class="text-lg font-medium text-center mb-4">{{ $t('completeProfile') }}</h3>
    
    <form @submit.prevent="handleSubmit" class="space-y-4">
      <div v-for="field in customFields" :key="field.meta_key" class="space-y-2">
        <label :for="field.meta_key" class="block text-sm font-medium text-gray-700">
          {{ field.name }}
          <span v-if="field.status === 'required'" class="text-red-500">*</span>
        </label>
        <input
          :id="field.meta_key"
          v-model="formData[field.meta_key]"
          type="text"
          :required="field.status === 'required'"
          class="appearance-none rounded-[32px] relative block w-full px-3 py-2 h-14 border border-[#e6e6e6] placeholder-gray-500 text-gray-900 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
        />
      </div>

      <div class="flex gap-4">
        <button
          type="submit"
          class="flex-1 flex justify-center items-center py-2 px-4 border border-transparent text-sm font-medium rounded-[32px] h-14 text-white bg-main hover:contrast-150 focus:outline-none focus:ring-0"
          :disabled="loading"
        >
          <span v-if="loading" class="spinner-loading"></span>
          <span v-else>{{ $t('continue') }}</span>
        </button>
        
        <button
          v-if="hasOptionalFieldsOnly"
          type="button"
          @click="skipCustomFields"
          class="flex-1 flex justify-center items-center py-2 px-4 border text-sm font-medium rounded-[32px] h-14 bg-white border-main text-main hover:bg-gray-50 focus:outline-none focus:ring-0"
        >
          {{ $t('skip') }}
        </button>
      </div>
    </form>
  </div>
</template>

<script setup>
import { ref, computed, watch } from 'vue'
import { useI18n } from 'vue-i18n'

const props = defineProps({
  customFields: {
    type: Array,
    required: true
  },
  loading: {
    type: Boolean,
    default: false
  }
})

const emit = defineEmits(['submit', 'skip'])
const { t } = useI18n()
const loading = ref(false)
const formData = ref({})

const hasOptionalFieldsOnly = computed(() => {
  return !props.customFields.some(field => field.status === 'required')
})

const handleSubmit = () => {
  const requiredFields = props.customFields.filter(field => field.status === 'required')
  const missingRequired = requiredFields.some(field => !formData.value[field.meta_key])
  
  if (missingRequired) {
    showError(t('customFieldsRequired'))
    return
  }
  
  loading.value = true
  emit('submit', formData.value)
}

const skipCustomFields = () => {
  emit('skip')
}

watch(() => loading.value, (newVal) => {
  if (!newVal) {
    loading.value = false
  }
})
</script> 