<template>
  <div class="flex items-center justify-center shadow-2xl rounded-2xl py-12 px-10 sm:px-14 lg:px-16 w-[500px] bg-white">
    <div class="max-w-md w-full space-y-8">
      <div v-if="settings.show_logo" class="flex justify-center">
        <img 
          :src="settings.siteLogo || '/wp-includes/images/w-logo-blue.png'" 
          alt="Site Logo" 
          class="h-16 w-auto mb-4"
        />
      </div>

      <!-- Reset Password Form -->
      <div v-if="showResetForm">
        <reset-password-form 
          :reset-key="resetKey"
          :reset-login="resetLogin"
        />
      </div>

      <!-- Phone Input Form -->
      <form v-else-if="!isOtpMode && !isEmailMode && !showUserInfoForm && !showCustomFields" 
            class="mt-8 space-y-6" 
            @submit.prevent="handleSubmit">
        <div>
          <vue-tel-input
            v-model="credentials.username"
            :mode="'international'"
            :preferred-countries="['IR']"
            :only-countries="['IR']"
            :default-country="'IR'"
            :valid-characters-only="true"
            @validate="validatePhone"
            @input="onPhoneInput"
            :input-options="{
              showDialCode: true,
              placeholder: t('phoneOrEmail')
            }"
            class="!border !border-[#e6e6e6] !rounded-3xl h-14"
          ></vue-tel-input>
        </div>

        <button
          type="button"
          @click="isEmailMode = true"
          class="hover:text-main text-sm text-center w-full mt-0 focus:outline-none ring-0"
        >
          {{ t('loginWithEmail') }}
        </button>
       
        <button 
          type="submit"
          class="w-full flex justify-center items-center py-2 px-4 border border-transparent text-sm font-medium rounded-[32px] h-14 text-white bg-main hover:contrast-150 focus:outline-none focus:ring-0"
          :disabled="loading || !isValidPhone"
        >
          <span v-if="loading" class="spinner-loading"></span>
          <span v-else>{{ t('sendOtp') }}</span>
        </button>
      </form>

      <!-- Other forms -->
      <div v-else-if="isOtpMode" class="space-y-4">
        <otp-input
          v-model="credentials.otp"
          :resend-delay="settings.settings?.resend_delay || 60"
          :otp-length="settings.settings?.otp_length || 4"
          @resend="handleResendOtp"
        />
        
        <div class="flex items-center gap-2">
          <button
            @click="handleBack"
            class="w-1/4 flex justify-center items-center py-2 px-4 border border-main text-sm font-medium rounded-[32px] h-14 text-black bg-white  focus:outline-none focus:ring-0"
          >
            {{ $t('back') }}
          </button>
          <button
            @click="verifyOtp"
            :disabled="loading"
            class="w-3/4 flex justify-center items-center py-2 px-4 border border-transparent text-sm font-medium rounded-[32px] h-14 text-white bg-main hover:contrast-150 focus:outline-none focus:ring-0"
          >
            <span v-if="loading" class="spinner-loading"></span>
            <span v-else>{{ $t('verify') }}</span>
          </button>
        </div>
      </div>

      <div v-else-if="isEmailMode">
        <form class="mt-8 space-y-6" @submit.prevent="handleEmailLogin">
          <div class="rounded-md -space-y-px">
            <div class="mb-4">
              <input
                type="email"
                v-model="credentials.email"
                required
                class="appearance-none rounded-[32px] relative block w-full px-3 py-2 h-14 border border-[#e6e6e6] placeholder-gray-500 text-gray-900 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
                :placeholder="t('email')"
              />
            </div>
            <div>
              <input
                type="password"
                v-model="credentials.password"
                required
                class="appearance-none rounded-[32px] relative block w-full px-3 py-2 h-14 border border-[#e6e6e6] placeholder-gray-500 text-gray-900 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
                :placeholder="t('password')"
              />
            </div>
          </div>

          <div class="flex items-center justify-between">
            <button
              type="button"
              @click="showForgotPassword = true"
              class="hover:text-main text-sm focus:outline-none ring-0"
            >
              {{ t('forgotPassword') }}
            </button>
          </div>

            <button
              type="button"
              @click="isEmailMode = false"
              class="hover:text-main text-sm focus:outline-none ring-0"
            >
              {{ t('loginWithPhone') }}
            </button>
         
          <button
            type="submit"
            class="w-full flex justify-center items-center py-2 px-4 border border-transparent text-sm font-medium rounded-[32px] h-14 text-white bg-main hover:contrast-150 focus:outline-none focus:ring-0"
            :disabled="loading"
          >
            <span v-if="loading" class="spinner-loading"></span>
            <span v-else>{{ t('login') }}</span>
          </button>

      
        </form>
      </div>

      <div v-else-if="showUserInfoForm">
        <user-info-form
          :loading="loading"
          :require-email="settings.settings?.require_email"
          :require-first-name="settings.settings?.require_first_name"
          :require-last-name="settings.settings?.require_last_name"
          :custom-fields="settings.settings?.custom_fields || []"
          :phone="credentials.username"
          @submit="handleUserInfoSubmit"
        />
      </div>

      <div v-else-if="showCustomFields">
        <custom-fields-form
          :custom-fields="settings.settings?.custom_fields || []"
          :loading="loading"
          @submit="handleCustomFields"
          @skip="handleSkipCustomFields"
        />
      </div>

      <div v-if="showForgotPassword" class="fixed inset-0 !m-0 bg-gray-500 bg-opacity-75 flex items-center justify-center z-50">
        <div class="bg-white p-8 rounded-lg max-w-md w-full mx-4">
          <h3 class="text-lg font-medium mb-4">{{ t('resetPassword') }}</h3>
          
          <form @submit.prevent="handleForgotPassword" class="space-y-4">
            <div>
              <input
                type="email"
                v-model="forgotPasswordEmail"
                required
                class="appearance-none rounded-[32px] relative block w-full px-3 py-2 h-14 border border-[#e6e6e6] placeholder-gray-500 text-gray-900 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
                :placeholder="t('email')"
              />
            </div>

            <div class="flex gap-4">
              <button
                type="button"
                @click="showForgotPassword = false"
                class="flex-1 flex justify-center items-center py-2 px-4 border border-main text-sm font-medium rounded-[32px] h-14 text-black bg-white focus:outline-none focus:ring-0"
              >
                {{ t('cancel') }}
              </button>
              
              <button
                type="submit"
                class="flex-1 flex justify-center items-center py-2 px-4 border border-transparent text-sm font-medium rounded-[32px] h-14 text-white bg-main hover:contrast-150 focus:outline-none focus:ring-0"
                :disabled="loading"
              >
                <span v-if="loading" class="spinner-loading"></span>
                <span v-else>{{ t('sendResetLink') }}</span>
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, computed, onMounted, watch, onUnmounted } from 'vue'
import { VueTelInput } from 'vue3-tel-input'
import 'vue3-tel-input/dist/vue3-tel-input.css'
import OtpInput from './OtpInput.vue'
import { showSuccess, showError } from '../../utils/swal'
import CustomFieldsForm from './CustomFieldsForm.vue'
import { t } from '../../utils/translate'
import EmailForm from './EmailForm.vue'
import UserInfoForm from './UserInfoForm.vue'
import ResetPasswordForm from './ResetPasswordForm.vue'

const smsir = window.sms_ir_login || {}
const $ = window.jQuery

const settings = ref({})

const fetchSettings = async () => {
  try {
    const data = {
      action: 'smsir_get_settings',
      nonce: smsir.nonce
    }

    const response = await $.post(smsir.ajaxUrl, data)
    if (response.success) {
      settings.value = response.data
    } else {
      throw new Error(response.data?.message || 'Failed to load settings')
    }
  } catch (err) {
    console.error('Failed to fetch settings:', err)
    showError(t('generalError'))
  }
}

const isOtpMode = ref(false)
const isEmailMode = ref(false)
const loading = ref(false)
const isValidPhone = ref(false)
const phoneNumber = ref('')

const credentials = ref({
  username: '',
  password: '',
  otp: ''
})

const validatePhone = (valid, number) => {
  isValidPhone.value = valid
}

const onPhoneInput = (formattedNumber, phoneObject) => {
  if (phoneObject) {
    const cleanNumber = phoneObject.nationalNumber.replace(/\s+/g, '');
    phoneNumber.value = `+98${cleanNumber}`;
    console.log('Formatted phone:', phoneNumber.value);
  }
}

const urlParams = new URLSearchParams(window.location.search)
const action = urlParams.get('action')
const key = urlParams.get('key')
const login = urlParams.get('login')

const showResetForm = ref(action === 'rp' && key && login)
const resetKey = ref(key)
const resetLogin = ref(login)

console.log('URL Params:', { action, key, login })
console.log('Show Reset Form:', showResetForm.value)

const handleSubmit = async () => {
  try {
    loading.value = true
    
    if (isOtpMode.value) {
      await verifyOtp()
    } else if (!isEmailMode.value) {
      await requestOtp()
    } else if (isEmailMode.value) {
      await loginWithEmail()
    }
  } catch (err) {
    showError(err.message)
  } finally {
    loading.value = false
  }
}

const requestOtp = async () => {
  try {
    console.log('Current phone number:', phoneNumber.value)
    
    if (!phoneNumber.value) {
      showError(t('pleaseEnterValidPhone'))
      return
    }

    if (!isValidPhone.value) {
      showError(t('pleaseEnterValidPhone'))
      return
    }

    loading.value = true

    credentials.value.username = phoneNumber.value

    const data = {
      action: 'smsir_request_otp',
      phone: phoneNumber.value,
      nonce: smsir.nonce
    };

    const response = await $.post(smsir.ajaxUrl, data);
    console.log('Response:', response);

    if (response.success) {
      isOtpMode.value = true;
      showSuccess(response.data.message || t('otpSent'))
    } else {
      showError(response.data?.message || t('generalError'));
      return;
    }
  } catch (err) {
    showError(err.message || t('generalError'));
    return false;
  } finally {
    loading.value = false
  }
}

const verifyOtp = async () => {
  try {
    loading.value = true
    
    const data = {
      action: 'smsir_verify_otp',
      phone: phoneNumber.value,
      otp: credentials.value.otp,
      nonce: smsir.nonce,
      is_modal: props.isModal ? 'true' : 'false'
    }

    const response = await $.post(smsir.ajaxUrl, data)

    if (response.success) {
      isOtpMode.value = false
      
      // If user exists, just log them in and return immediately
      if (response.data.user_exists) {
        handleLoginSuccess(response)
        return
      }

      // Only for new users: check if we need additional info
      if (response.data.needs_user_info) {
        showUserInfoForm.value = true
        showCustomFields.value = false
        showEmailForm.value = false
      } else if (response.data.needs_custom_fields) {
        showCustomFields.value = true
        showUserInfoForm.value = false
        showEmailForm.value = false
      } else {
        handleLoginSuccess(response)
      }
    } else {
      throw new Error(response.data?.message || t('invalidOtp'))
    }
  } catch (err) {
    showError(err.message || t('generalError'))
  } finally {
    loading.value = false
  }
}

const loginWithEmail = async () => {
  try {
    const data = {
      action: 'smsir_login_email',
      email: credentials.value.username,
      password: credentials.value.password,
      nonce: smsir.nonce,
      is_modal: props.isModal ? 'true' : 'false'
    };

    const response = await $.post(smsir.ajaxUrl, data);
    console.log('Login Response:', response);

    if (response.success) {
      showSuccess(response.data.message || t('loginSuccess'))
      if (props.isModal) {
        emit('login-success')
      }
      setTimeout(() => {
        window.location.href = response.data.redirect_url;
      }, 1500)
    } else {
      throw new Error(response.data?.message || t('invalidCredentials'));
    }
  } catch (err) {
    showError(err.message || t('generalError'));
  }
}

const showForgotPassword = ref(false)
const forgotPasswordEmail = ref('')

const handleForgotPassword = async (e) => {
  e.preventDefault()
  
  try {
    loading.value = true
    const data = {
      action: 'smsir_forgot_password',
      email: forgotPasswordEmail.value,
      nonce: smsir.nonce
    }

    const response = await $.post(smsir.ajaxUrl, data)

    if (response.success) {
      showSuccess(response.data.message || t('resetLinkSent'))
      showForgotPassword.value = false
      forgotPasswordEmail.value = ''
    } else {
      throw new Error(response.data?.message || t('emailNotFound'))
    }
  } catch (err) {
    showError(err.message || t('generalError'))
  } finally {
    loading.value = false
  }
}

const resetPassword = ref('')
const resetPasswordConfirm = ref('')
const isResetMode = ref(false)

onMounted(async () => {
  await fetchSettings()
  
  if (smsir.isResetMode && smsir.resetKey && smsir.resetLogin) {
    isResetMode.value = true;
    resetKey.value = smsir.resetKey;
    resetLogin.value = smsir.resetLogin;
  }
})

const handleResetPassword = async () => {
  try {
    if (resetPassword.value !== resetPasswordConfirm.value) {
      showError(t('passwordsDoNotMatch'))
      return
    }

    loading.value = true

    const data = {
      action: 'smsir_reset_password',
      key: resetKey.value,
      login: resetLogin.value,
      password: resetPassword.value,
      nonce: smsir.nonce
    }

    const response = await $.post(smsir.ajaxUrl, data)

    if (response.success) {
      showSuccess(response.data.message)
      setTimeout(() => {
        window.location.href = response.data.redirect_url
      }, 1500)
    } else {
      throw new Error(response.data?.message || t('generalError'))
    }
  } catch (err) {
    showError(err.message || t('generalError'))
  } finally {
    loading.value = false
  }
}

const otpInputRef = ref(null)

const countdown = ref(settings.settings?.resend_delay || 60)
let timer = null

const startCountdown = () => {
  countdown.value = settings.settings?.resend_delay || 60
  clearInterval(timer)
  timer = setInterval(() => {
    if (countdown.value > 0) {
      countdown.value--
    } else {
      clearInterval(timer)
    }
  }, 1000)
}

const handleResendOtp = async () => {
  try {
    loading.value = true
    const data = {
      action: 'smsir_request_otp',
      phone: phoneNumber.value,
      nonce: smsir.nonce
    }

    const response = await $.post(smsir.ajaxUrl, data)

    if (response.success) {
      showSuccess(response.data.message || t('otpResent'))
    } else {
      throw new Error(response.data?.message || t('generalError'))
    }
  } catch (err) {
    showError(err.message || t('generalError'))
  } finally {
    loading.value = false
  }
}

watch(isOtpMode, (newValue) => {
  if (newValue) {
    startCountdown()
  } else {
    clearInterval(timer)
  }
})

onUnmounted(() => {
  clearInterval(timer)
})

const handleBack = () => {
  isOtpMode.value = false
  credentials.value.otp = ''
  clearInterval(timer)
  countdown.value = 60
}

const props = defineProps({
  isModal: {
    type: Boolean,
    default: false
  }
})

const emit = defineEmits(['login-success'])

const showCustomFields = ref(false)
const customFieldsData = ref({})

const handleCustomFields = async (data) => {
  try {
    loading.value = true
    const submitData = {
      action: 'smsir_save_custom_fields',
      phone: credentials.value.username,
      custom_fields: data,
      nonce: smsir.nonce,
      is_modal: props.isModal ? 'true' : 'false'
    }

    const response = await $.post(smsir.ajaxUrl, submitData)

    if (response.success) {
      showSuccess(response.data.message || t('loginSuccess'))
      if (props.isModal) {
        emit('login-success')
      }
      setTimeout(() => {
        window.location.href = response.data.redirect_url || '/'
      }, 1500)
    } else {
      throw new Error(response.data?.message || t('generalError'))
    }
  } catch (err) {
    showError(err.message || t('generalError'))
  } finally {
    loading.value = false
  }
}

const handleSkipCustomFields = async () => {
  try {
    const data = {
      action: 'smsir_complete_login',
      phone: credentials.value.username,
      nonce: smsir.nonce,
      is_modal: props.isModal ? 'true' : 'false'
    }

    const response = await $.post(smsir.ajaxUrl, data)

    if (response.success) {
      handleLoginSuccess(response)
    } else {
      throw new Error(response.data?.message || t('generalError'))
    }
  } catch (err) {
    showError(err.message || t('generalError'))
  }
}

const handleEmailLogin = async () => {
  try {
    loading.value = true
    const data = {
      action: 'smsir_login_email',
      email: credentials.value.email,
      password: credentials.value.password,
      nonce: smsir.nonce,
      is_modal: props.isModal ? 'true' : 'false'
    }

    const response = await $.post(smsir.ajaxUrl, data)

    if (response.success) {
      handleLoginSuccess(response)
    } else {
      throw new Error(response.data?.message || t('invalidCredentials'))
    }
  } catch (err) {
    showError(err.message || t('generalError'))
  } finally {
    loading.value = false
  }
}

const showEmailForm = ref(false)


const showUserInfoForm = ref(false)

const handleUserInfoSubmit = async (data) => {
  try {
    loading.value = true
    const submitData = {
      action: 'smsir_save_custom_fields',
      phone: credentials.value.username,
      email: data.email,
      first_name: data.first_name,
      last_name: data.last_name,
      custom_fields: data.custom_fields || {},
      nonce: smsir.nonce,
      is_modal: props.isModal ? 'true' : 'false'
    }

    const response = await $.post(smsir.ajaxUrl, submitData)

    if (response.success) {
      showSuccess(response.data.message || t('loginSuccess'))
      if (props.isModal) {
        emit('login-success')
      }
      setTimeout(() => {
        window.location.href = response.data.redirect_url || '/'
      }, 1500)
    } else {
      throw new Error(response.data?.message || t('generalError'))
    }
  } catch (err) {
    showError(err.message || t('generalError'))
  } finally {
    loading.value = false
  }
}

const handleLoginSuccess = async (response) => {
  try {
    showSuccess(response.data.message || t('loginSuccess'))
    
    if (props.isModal) {
      emit('login-success')
    }
    
    // Redirect after successful login
    setTimeout(() => {
      window.location.href = response.data.redirect_url || '/'
    }, 1500)
  } catch (err) {
    showError(err.message || t('generalError'))
  }
}

const hasCustomFields = computed(() => {
  return settings.value?.settings?.custom_fields?.length > 0
})
</script>

<style>
.vue-tel-input {
  direction: ltr !important;
}
.vue-tel-input input {
  text-align: left !important;
}
.vti__dropdown {
  direction: ltr;
}
.vti__input {
  direction: ltr;
  border-radius: 32px;
  height: 54px;
}
.vti__dropdown-list {
  direction: ltr;
  text-align: left;
}
</style>

<style scoped>
.fixed {
  z-index: 1000;
}

.modal-content {
  z-index: 1001;
}
</style> 