<script>
export default {
    props: {
        settings: Object,
    },
    data() {
    return {
      syncing: false,
      syncResult: null,
      custom_fields: [],
      wc_email_optional: false,

    };
  },

  methods: {
    async syncDigitsUsers() {
      try {
        this.syncing = true;
        this.syncResult = null;
        
        const response = await fetch(window.sms_ir_login.ajaxUrl, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/x-www-form-urlencoded',
          },
          body: new URLSearchParams({
            action: 'smsir_sync_digits_users',
            nonce: window.sms_ir_login.nonce
          })
        });
        
        const data = await response.json();
        
        this.syncResult = {
          success: data.success,
          message: data.data.message
        };
      } catch (error) {
        this.syncResult = {
          success: false,
          message: 'خطا در هماهنگ سازی اطلاعات'
        };
      } finally {
        this.syncing = false;
      }
    },
    addField() {
      if (!this.settings.settings.custom_fields) {
        this.settings.settings.custom_fields = [];
      }
      this.settings.settings.custom_fields.push({
        name: '',
        meta_key: '',
        status: 'optional'
      });
    },
    removeField(index) {
      this.settings.settings.custom_fields.splice(index, 1);
    }
  }
};
</script>
