<template>
    <div  class="mb-5 container m-auto flex flex-col md:flex-row mt-8 gap-4">
      <aside class="md:w-3/12 xl:w-2/12 space-y-5 space-y-reverse">
        <a href="">
          <img class="w-4 md:w-auto" src="../img/logo.svg" alt="">

        </a>
        </aside>
        <article v-if="accountStats" class="w-full md:w-9/12 xl:w-10/12 flex items-center gap-3">
          <div class="w-full flex items-center gap-3 p-4 shadow-md bg-white rounded-xl">
      <div class="w-10 flex items-center justify-center">
        <i class="text-2xl icon-coins"></i>
      </div>
      <div class="stat-content">
        <h4 class="text-sm font-bold text-[#666]">{{ $t('account.credit') }}</h4>
        <p>{{ formatNumber(accountStats.credit) }} {{ $t('SMS') }}</p>
      </div>
    </div>
    <div class="w-full flex items-center gap-3 p-4 shadow-md bg-white rounded-xl">
      <div class="w-10 flex items-center justify-center">
        <i class="text-2xl icon-comment-alt"></i>
      </div>
      <div class="stat-content">
        <h4 class="text-sm font-bold text-[#666]">{{ $t('account.active_lines') }}</h4>
        <p>{{ formatNumber(accountStats.active_lines) }}</p>
      </div>
    </div>
    <div class="w-full flex items-center gap-3 p-4 shadow-md bg-white rounded-xl">
      <div class="w-10 flex items-center justify-center">
        <i class="text-2xl icon-inbox-out"></i>
      </div>
      <div class="stat-content">
        <h4 class="text-sm font-bold text-[#666]">{{ $t('account.today_sent') }}</h4>
        <p>{{ formatNumber(accountStats.today_sent) }}</p>
      </div>
    </div>
    <div class="w-full flex items-center gap-3 p-4 shadow-md bg-white rounded-xl">
      <div class="w-10 flex items-center justify-center">
        <i class="text-2xl icon-inbox-in"></i>
      </div>
      <div class="stat-content">
        <h4 class="text-sm font-bold text-[#666]">{{ $t('account.today_received') }}</h4>
        <p>{{ formatNumber(accountStats.today_received) }}</p>
      </div>
    </div>
        </article>
 
  </div>
  <div class="container m-auto flex flex-col md:flex-row mt-8 gap-4">
    <aside class="md:w-3/12 xl:w-2/12 space-y-5 space-y-reverse">
      <div
          class="tab-section flex items-center rounded-[32px] bg-white p-4 h-16 md:block md:h-auto overflow-hidden overflow-x-scroll md:overflow-auto">
        <ul class="flex md:flex-wrap text-sm leading-5 text-main-400 space-x-1 md:space-x-0 md:space-y-1 md:flex [&>*]:cursor-pointer  [&>*]:md:w-full [&>*]:flex [&>*]:items-center gap-1 [&>*]:gap-1 [&>*]:bg-[#f5f7fa] [&>*]:rounded-2xl [&>*]:w-40 [&>*]:!text-xs [&>*]:md:text-base flex-row [&>*]:md:!mb-0">
      
          <li class="main tab-title-selected p-3" :class="{'active': currentTab == 'general'}"
              @click.prevent="handleTabClick('general')">
            <p>
              {{ $t("generalSettings") }}</p>
              <i v-if="currentTab === 'general'"  class="icon-dropdown  mr-auto text-[12px] text-main rotate-90"></i>
          </li>
          <li class="main tab-title-selected p-3" :class="{'active': currentTab == 'login'}"
              @click.prevent="handleTabClick('login')">
            <p>
              {{ $t("loginSettings") }}</p>
              <i v-if="currentTab === 'login'"  class="icon-dropdown  mr-auto text-[12px] text-main rotate-90"></i>
          </li>
          <li class="main tab-title-selected p-3" :class="{'active': currentTab == 'shortcode'}"
              @click.prevent="handleTabClick('shortcode')">
            <p>
              {{ $t("shortCodes") }}</p>
              <i v-if="currentTab === 'shortcode'"  class="icon-dropdown  mr-auto text-[12px] text-main rotate-90"></i>
          </li>
          <li class="main tab-title-selected p-3" :class="{'active': currentTab == 'template'}"
              @click.prevent="handleTabClick('template')">
            <p>
              {{ $t("templateManager") }}</p>
              <i v-if="currentTab === 'template'"  class="icon-dropdown  mr-auto text-[12px] text-main rotate-90"></i>
          </li>
        
        </ul>
      </div>
    </aside>
 
    <GeneralSettings :settings="checkedSettings" v-show="currentTab == 'general'"/>
    <LoginSettings :settings="checkedSettings" v-show="currentTab == 'login'"/>
    <ShortCodes :settings="checkedSettings" v-show="currentTab == 'shortcode'"/>
    <TemplateManager :settings="checkedSettings" v-show="currentTab == 'template'"/>
  </div>
  <div class="container m-auto mt-4">
    <div class="flex flex-col md:flex-row items-center gap-5 justify-end relative">
  

      <button @click.prevent="saveSettings"  v-show="readOnly.indexOf(currentTab) === -1"
              class="z-50 BTNMAIN px-9 items-center text-xs  md:text-base justify-center w-full md:w-max focus:outline-none focus:border-none hover:bg-white hover:text-main"
              :class="{
          'pointer-events-none': saving,
        }" href="#">
        <span v-if="saving">{{ $t("Saving") }}</span>
        <span v-else>{{ $t("SaveChanges") }}</span>
      </button>
   
    
    </div>
  </div>

</template>

<script>
import Swal from "sweetalert2";
import axios from "axios";
import LoginSettings from "./tabs/LoginSettings.vue";
import GeneralSettings from "./tabs/GeneralSettings.vue";
import ShortCodes from "./tabs/ShortCodes.vue";
import TemplateManager from "./tabs/TemplateManager.vue";
export default {
  components: {
    GeneralSettings,
    LoginSettings,
    ShortCodes,
    TemplateManager,
  },
  data() {
    return {
      readOnly: ['manual','buyedProducts','errors'],
        sms_ir_login: window.sms_ir_login || "",
        currentTab: 'general',
        selectedTab: 'general',
        currentSub: 1,
        buyed_product:{},
        defaultSettings: {
          settings: {
        },
      },
      checkedSettings: {
        settings: {
        },      
      },
      show: true,
      warning: false,
      saving: false,
      accountStats: null,
      accountStatsError: null,
        MainLogo: "/wp-content/plugins/smsir/app/src/assets/img/logo.svg"
    };
  },
  created() {
    this.fetchSettings();
  },
  mounted() {
    this.selectTabFromQuery();
    window.addEventListener(
        "popstate",
        this.selectTabFromQuery
    );
    this.fetchAccountStats()
  },
  methods: {
    selectTabFromQuery() {
      const url = new URL(window.location.href);
      const tab = url.searchParams.get("tab");
      if (tab) {
        this.currentTab = tab;
      }
    },
    async fetchSettings() {
      try {
        const response = await axios.post(`${this.sms_ir_login.ajaxUrl}`,{nonce:`${this.sms_ir_login.nonce}`,action:"sms_ir_get_settings"},
            {
              headers: {
                'Content-Type': 'application/x-www-form-urlencoded' 
              },
              withCredentials: true,
            });

        this.checkedSettings = response.data;
      } catch (error) {
        console.error(
            "Error fetching settings:",
            error
        );
      }
    },
    handleTabClick(index, sub = 1) {
      this.currentTab = index;
      this.currentSub = sub;
      this.show = true;
      this.redirect = false;
      const url = new URL(window.location.href);
      url.searchParams.set("tab", index);
      window.history.pushState({}, "", url);

    },
    async saveSettings() {
      try {
        this.saving = true;
        this.checkedSettings
        let data=this.checkedSettings;
        data.nonce=this.sms_ir_login.nonce;
        data.action="sms_ir_save_settings";
        const response = await axios.post(`${this.sms_ir_login.ajaxUrl}`, data,
            {
              headers: {
                'Content-Type': 'application/x-www-form-urlencoded' 
              },
              withCredentials: true,
            });
        if (response.data.setting) {
          this.checkedSettings = response.data.setting;
        }
        if (response.data.success) {
          this.saving = false;
          Swal.fire({
            text:
                response.data.message ||
                this.$t("SettingsSavedSuccessfully"),
            icon: "success",
            toast: true,
            position: "top-start",
            showConfirmButton: false,
            timer: 3000,
            timerProgressBar: true,
            customClass: {
              popup: "smsir-swal",
            },
          });
        }
      } catch (error) {
        this.saving = false;
        let errorMessage =
        this.$t("SettingsSaveError");

        if (
            error.response &&
            error.response.data &&
            error.response.data.message
        ) {
          errorMessage =
              error.response.data.message;
        }

        Swal.fire({
          text: errorMessage,
          icon: "error",
          toast: true,
          position: "top-start",
          showConfirmButton: false,
          timer: 3000,
          timerProgressBar: true,
          customClass: {
            popup: "smsir-swal",
          },
        });
        console.error(
            "Error saving settings:",
            error
        );
      }
    },
    async fetchAccountStats() {
      try {
        const response = await axios.post(window.sms_ir_login.ajaxUrl, new URLSearchParams({
          action: 'sms_ir_get_account_stats',
          nonce: window.sms_ir_login.nonce
        }), {
          headers: {
            'Content-Type': 'application/x-www-form-urlencoded'
          }
        })

        this.accountStats = response.data.data
      } catch (error) {
        this.accountStatsError = error.response?.data?.message || this.$t('errors.account_stats_fetch_failed')
        console.error('Failed to fetch account stats:', error)
      }
    },
    formatNumber(num) {
      return num?.toLocaleString('fa-IR') || '0'
    }
  }
}
</script>

