<template>
  <div class="edit-phone-container">
    <!-- Current Phone Display -->
    <div class="flex items-center gap-1 current-phone mb-4">

      <div class="w-1/2">
      <vue-tel-input
        v-model="phone"
        v-model:formatted="formattedPhone"
        :mode="'international'"
        :preferred-countries="['IR']"
        :only-countries="['IR']"
        :default-country="'IR'"
        :valid-characters-only="true"
        @validate="validatePhone"
        @input="onPhoneInput"
        :input-options="{
          showDialCode: true,
          placeholder: $t('newPhoneNumber')
        }"
        class="!border !border-[#e6e6e6] !rounded-3xl h-14 mt-1"
      ></vue-tel-input>
    </div>
      <div class="w-1/2 current-phone-value flex items-center px-4 py-2 bg-gray-100 rounded-[32px] h-14">
        {{ smsir.currentPhone || $t('noPhoneNumber') }}
      </div>

    </div>

    <!-- New Phone Input -->
   

    <!-- Verify Button -->
    <button
      v-if="showVerifyButton"
      type="button"
      @click="requestOtp"
      :disabled="loading"
      class="mt-3 w-full flex justify-center items-center py-2 px-4 border border-transparent text-sm font-medium rounded-[32px] h-14 text-white bg-main hover:contrast-150 focus:outline-none focus:ring-0"
    >
      <span v-if="loading" class="spinner-loading"></span>
      <span v-else>{{ $t('verifyPhone') }}</span>
    </button>

    <!-- OTP Input Section -->
    <div v-if="showOtpSection" class="mt-4">
      <otp-input
        v-model="otpCode"
        :resend-delay="60"
        @resend="handleResendOtp"
      />
      
      <div class="flex gap-4 mt-3">
        <button
          @click="handleBack"
          class="flex-1 flex justify-center items-center py-2 px-4 border border-main text-sm font-medium rounded-[32px] h-14 text-black bg-white focus:outline-none focus:ring-0"
        >
          {{ $t('back') }}
        </button>
        <button
          @click="verifyOtp"
          :disabled="loading"
          class="flex-1 flex justify-center items-center py-2 px-4 border border-transparent text-sm font-medium rounded-[32px] h-14 text-white bg-main hover:contrast-150 focus:outline-none focus:ring-0"
        >
          <span v-if="loading" class="spinner-loading"></span>
          <span v-else>{{ $t('verify') }}</span>
        </button>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, watch, onMounted, computed } from 'vue'
import { VueTelInput } from 'vue3-tel-input'
import OtpInput from '../auth/OtpInput.vue'
import { showSuccess, showError } from '../../utils/swal'
import { t } from '../../utils/translate'

const smsir = window.smsir || {}
const $ = window.jQuery

const phone = ref('')
const formattedPhone = ref('')
const isValidPhone = ref(false)
const loading = ref(false)
const showOtpSection = ref(false)
const otpCode = ref('')
const verifiedPhoneInput = ref(null)

// Add watcher for phone input
watch(phone, (newValue) => {
  if (newValue) {
    const digitsOnly = newValue.replace(/\D/g, '')
    if (digitsOnly.length > 11) {
      const truncated = digitsOnly.slice(0, 11)
      phone.value = `+98${truncated}`
    }
  }
}, { immediate: true })

onMounted(() => {
  const currentPhone = smsir.currentPhone || ''
  
  if (currentPhone) {
    const cleanNumber = currentPhone.replace(/^\+/, '').replace(/^0+/, '')
    
    // If number doesn't start with 98, add it
    const fullNumber = cleanNumber.startsWith('98') ? cleanNumber : `98${cleanNumber}`
    
    phone.value = `+${fullNumber}`
    
    formattedPhone.value = phone.value
    
    isValidPhone.value = true
  }
  
  verifiedPhoneInput.value = document.getElementById('verified-phone')
  if (verifiedPhoneInput.value) {
    verifiedPhoneInput.value.value = currentPhone
  }
})

const showVerifyButton = computed(() => {
  return isValidPhone.value && phone.value && phone.value !== smsir.currentPhone
})

const validatePhone = (valid, number, country, e) => {
  isValidPhone.value = valid
}

const onPhoneInput = (formattedNumber, { number, isValid, country }) => {
  if (number) {
    const digitsOnly = number.replace(/\D/g, '')
    if (digitsOnly.length > 11) {
      return
    }
    phone.value = number
    formattedPhone.value = formattedNumber
  }

  if (verifiedPhoneInput.value) {
    verifiedPhoneInput.value.value = isValid ? number : smsir.currentPhone
  }
}

const requestOtp = async () => {
  try {
    if (!phone.value || !isValidPhone.value) {
      showError(t('pleaseEnterValidPhone'))
      return
    }

    loading.value = true
    const response = await $.post(smsir.ajaxUrl, {
      action: 'smsir_request_change_phone_otp',
      phone: phone.value,
      nonce: smsir.nonce
    })

    if (response.success) {
      showOtpSection.value = true
      showSuccess(response.data.message || t('otpSent'))
    } else {
      throw new Error(response.data?.message || t('generalError'))
    }
  } catch (err) {
    showError(err.message || t('generalError'))
  } finally {
    loading.value = false
  }
}

const verifyOtp = async () => {
  try {
    loading.value = true
    const response = await $.post(smsir.ajaxUrl, {
      action: 'smsir_verify_change_phone',
      phone: phone.value,
      otp: otpCode.value,
      nonce: smsir.nonce
    })

    if (response.success) {
      if (verifiedPhoneInput.value) {
        verifiedPhoneInput.value.value = phone.value
      }
      showOtpSection.value = false
      showSuccess(t('phoneVerified'))
    } else {
      throw new Error(response.data?.message || t('invalidOtp'))
    }
  } catch (err) {
    showError(err.message || t('generalError'))
  } finally {
    loading.value = false
  }
}

const handleResendOtp = async () => {
  await requestOtp()
}

const handleBack = () => {
  showOtpSection.value = false
  otpCode.value = ''
}
</script>

